/** Published file holding the EGM96 grid, generated by scripts/prepare-assets.ts. */
export const GEOID_FILE = 'egm96-1deg.bin';
export const GEOID_STEP = 1;

export function geoidGridSize(step: number) {
  return { rows: Math.round(180 / step) + 1, cols: Math.round(360 / step) };
}

/** Height of mean sea level above the WGS84 ellipsoid, bilinearly interpolated. */
export type Geoid = (lat: number, lon: number) => number;

export function createGeoid(buffer: ArrayBuffer, step = GEOID_STEP): Geoid {
  const grid = new Int16Array(buffer);
  const { rows, cols } = geoidGridSize(step);
  if (grid.length !== rows * cols) throw new Error(`Geoid grid has ${grid.length} values, expected ${rows * cols}`);
  const at = (r: number, c: number) => grid[r * cols + (((c % cols) + cols) % cols)]! / 10;

  return (lat, lon) => {
    const y = Math.min(rows - 1, Math.max(0, (90 - lat) / step));
    const x = (((lon % 360) + 360) % 360) / step;
    const r0 = Math.min(rows - 2, Math.floor(y));
    const c0 = Math.floor(x);
    const fy = y - r0;
    const fx = x - c0;
    const top = at(r0, c0) * (1 - fx) + at(r0, c0 + 1) * fx;
    const bottom = at(r0 + 1, c0) * (1 - fx) + at(r0 + 1, c0 + 1) * fx;
    return top * (1 - fy) + bottom * fy;
  };
}
